      method: "POST",
      url: `/projects/${projectId}/templates/${templateId}/compile`,
      payload: {
        context: { name: "John" },
        platforms: ["x", "instagram"],
      },
    });

    expect(response.statusCode).toBe(200);
  });

  it("should compile with A/B test config", async () => {
